use pizza_sales;
select * from p;
select * from p
where pizza_id is null
and order_id is null
and 
pizza_name_id is null
and 
quality is null
and 
order_date is null
and 
order_time is null
and 
unit_price is null
and 
total_price is null
and 
pizza_size is null
and 
pizza_categroy is null
and 
pizza_ingredients is null
and 
pizza_name is null;
-- Question 1:
              -- Management wants to know the total revenue generated by the business.
SELECT 
    SUM(total_price) as revenue
FROM
    p;
    -- ans : Total Revenue = $817,860.
-- Question 2:    
            -- Management wants to know the total number of orders placed.
SELECT 
    COUNT( distinct pizza_id) as No_Orders
FROM
    p; 
-- Ans : Total NUmber of orders = 48620    
    
         
 -- Question 3:           
              -- Management wants to know the total number of pizzas sold.
 SELECT 
    SUM(quantity) as Pizza_sold
FROM
    p;
    -- Ans : Pizza_sold = 49574
    
 -- Question 4:   
            -- Which pizza category generates the highest revenue?
select sum(total_price) as revenue,
pizza_category
from p
group by pizza_category
order by revenue desc;
-- Ans : Highest revenue = $220053 by "Classic" Pizzas

-- Question 5:
			  -- Which pizza size generates the highest revenue?
SELECT 
    SUM(total_price) AS revenue, pizza_size
FROM
    p
GROUP BY pizza_size
ORDER BY revenue DESC;
-- Ans : Highest revenue = $375318 by "L" Size

-- Question 6:
              -- Management wants to identify the 10 pizzas that generated the highest revenue.
select sum(total_price) as revenue ,
pizza_name
from p
group by pizza_name
order by revenue desc
limit 10;
-- Question 7:
              -- Management wants to identify the 10 pizzas that generated the lowest revenue.
select sum(total_price) as revenue ,
pizza_name
from p
group by pizza_name
order by revenue 
limit 10;			

-- Question 8:
              -- Management wants to analyze the revenue contribution of each pizza category.
              
select 
pizza_category,
sum(total_price) as revenue from p
group by pizza_category ;

-- Question 9:
              -- Management wants to identify which pizza size sells the highest quantity.

SELECT SUM(quantity) quantity_sold,
pizza_size
from  p
group by pizza_size 
order by quantity_sold desc
limit 1;
-- Ans : Highest quantity Sold = 18956 By Pizza_size "L"		
            
 -- Question 10:	
              -- Management wants to identify the days of the week that generate the highest revenue.
select dayname(str_to_date(order_date,"%d-%m-%y")) as days ,
sum(total_price) as revenue
 from p 
 group by  days
 order by revenue desc;
 select * from p;
-- Question 11:
              -- Management wants to identify the hours of the day that receive the most orders.
             select hour(order_time) as hour,
             count(*) as Total_orders
             from p
             group by hour
             order by total_orders desc;
              
-- Question 12:
              -- Management wants to determine which pizza category has the highest average order value.
               select avg(total_price) as avg_order_value,
              pizza_category
              from p
              group by pizza_category
              order by avg_order_value desc;

-- Question 13:
              -- Management wants to compare each category's revenue against the overall average category revenue.
with cta as (
              select 
              pizza_category ,
              sum(total_price) as revenue
              from p
              group by pizza_category)
              select * ,
              (select avg(revenue) 
              from cta) as avg_revenue
              from cta;
              
-- Question 14:
              -- Management wants to identify pizzas that generate more revenue than the average pizza revenue within their own category.
			with cta as ( select 
              pizza_name,
              pizza_category,
              sum(total_price) as revenue
              from p group by pizza_name,pizza_category)
              select pizza_name,
              pizza_category, revenue
              from cta c1
              where revenue >
              (select avg(revenue) as avg_revenue 
              from cta c2
              where c1.pizza_category=c2.pizza_category);
              
-- Question 15:
              -- Management wants to rank top 3 pizzas by revenue within each pizza category.
     with cta as (         
select sum(total_price) as revenue,
pizza_category,pizza_name from p
group by pizza_category,pizza_name)
select * from
(select pizza_category,pizza_name,revenue,
rank() over(partition by pizza_category order by revenue desc) as rnk from cta) t
where rnk <= 3;

              